package com.kaipai.controller.api.ai; import com.kaipai.common.exception.BizException; import com.kaipai.common.result.R; import com.kaipai.model.ai.dto.*; import com.kaipai.service.ai.ProfileImportService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/ai/profile-import") @RequiredArgsConstructor public class AiProfileImportController { private final ProfileImportService service; @PostMapping("/extract") public R<ProfileImportExtractionRespDTO> extract(Authentication auth,@Valid @RequestBody ProfileImportExtractReqDTO request){return R.ok(service.extract(userId(auth),request));} private Long userId(Authentication auth){if(auth==null||!(auth.getPrincipal() instanceof Long id))throw new BizException("未登录或登录态失效");return id;}}
